// Turn the model's text output into a clean JSON object for the frontend.
const item = $input.first().json;
let out = item.output ?? item.text ?? item.response ?? '';
if (out && typeof out === 'object') {
  return [{ json: out }];
}
out = String(out).trim();
const fence = out.match(/```(?:json)?\s*([\s\S]*?)```/i);
if (fence) out = fence[1].trim();
let parsed;
try {
  parsed = JSON.parse(out);
} catch (e) {
  parsed = { kind: 'unknown', reply: "Sorry, I couldn't parse that request. Try 'drop the senior center' or 'put the shelter first'.", action: null };
}
if (!parsed.kind) parsed.kind = 'unknown';
if (parsed.reply == null) parsed.reply = '';
return [{ json: parsed }];
